mapper.select:
SELECT t.id, t.task_no, p.name AS toilet_name, a.area_name, t.cleaning_frequency, t.cleaning_time, t.cleaning_content, t.cleaning_standard, sps.name AS plan_status_name, GROUP_CONCAT(DISTINCT u.user_name SEPARATOR ',') AS cleaner_names, t.completion_rate, t.is_abnormal, t.abnormal_desc, t.create_time, t.complete_time, t.handle_result, t.proof_urls, t.handle_duration, t.satisfaction, t.stat_period FROM public_toilet_cleaning_task t LEFT JOIN public_toilet p ON t.toilet_id = p.toilet_id LEFT JOIN sys_area a ON p.area_code = a.area_code LEFT JOIN sys_plan_status sps ON t.plan_status_id = sps.sys_plan_status_id LEFT JOIN sys_user u ON JSON_CONTAINS(t.cleaner_ids, CONCAT('"', u.user_id, '"'))
t.deleted = 0
AND t.task_no LIKE CONCAT('%', #{reqVO.taskNo}, '%')
AND t.toilet_id = #{reqVO.toiletId}
AND t.is_abnormal = #{reqVO.isAbnormal}
AND t.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
AND t.plan_status_id IN
#{item}
AND t.complete_time BETWEEN #{reqVO.completeTime[0]} AND #{reqVO.completeTime[1]}
AND t.handle_result LIKE CONCAT('%', #{reqVO.handleResult}, '%')
AND t.handle_duration BETWEEN #{reqVO.handleDuration[0]} AND #{reqVO.handleDuration[1]}
AND t.satisfaction = #{reqVO.satisfaction}
AND t.stat_period = #{reqVO.statPeriod}
GROUP BY t.id, t.task_no, p.name, a.area_name, t.cleaning_frequency, t.cleaning_time, t.cleaning_content, t.cleaning_standard, sps.name, t.completion_rate, t.is_abnormal, t.abnormal_desc, t.create_time ORDER BY t.create_time DESC
